// Venues and what's drawn on them: the venue book, the LX Factory theatre seat map (chairs
// generated by the editor's own lib/seating/generate.js) with the Summit's VIP seats sold, the
// Pier 17 gala dinner plan, and the LX Factory expo hall with its sponsor booths.

import { personId } from "../cast.js";
import { generateSeats } from "../../seating/generate.js";
import { EVENT, VENUE, VENUES } from "./catalog.js";
import { ORDER_ROWS } from "./orders.js";
import { coverArt } from "./art.js";
import { PROJECT_ID, daysAgo, sid } from "./helpers.js";

const MAP = { mainHall: sid("seatMap", 1), gala: sid("seatMap", 2) };
export const HALL = { expo: sid("hallMap", 1) };

const LAYOUT = (rows, seatsPerRow, extra = {}) => ({ rows, seatsPerRow, rowLabels: "alpha", rowLabelStart: "A", numbering: "continental", curve: 18, rake: 10, aisleAfter: [], ...extra });

// [map, name, kind, x, y, width, height, rotation, layout, capacity]
const SECTIONS = [
  [MAP.mainHall, "VIP Front Stalls", "seated", 30, 22, 40, 12, 0, LAYOUT(4, 16), 0],
  [MAP.mainHall, "Stalls Left", "seated", 6, 38, 26, 30, -8, LAYOUT(10, 12, { aisleAfter: [6] }), 0],
  [MAP.mainHall, "Stalls Centre", "seated", 35, 38, 30, 30, 0, LAYOUT(10, 16, { aisleAfter: [8] }), 0],
  [MAP.mainHall, "Stalls Right", "seated", 68, 38, 26, 30, 8, LAYOUT(10, 12, { aisleAfter: [6] }), 0],
  [MAP.mainHall, "Balcony", "seated", 15, 74, 70, 16, 0, LAYOUT(5, 28, { aisleAfter: [9, 18] }), 0],
  [MAP.mainHall, "Standing — Back Bar", "ga", 30, 92, 40, 6, 0, {}, 120],
  [MAP.gala, "Head Table", "seated", 40, 14, 20, 6, 0, LAYOUT(1, 12, { curve: 0, rake: 0 }), 0],
  [MAP.gala, "Tables 1–6", "seated", 12, 32, 34, 40, 0, LAYOUT(6, 10, { curve: 0, rake: 0, rowLabels: "numeric", rowLabelStart: "1" }), 0],
  [MAP.gala, "Tables 7–12", "seated", 54, 32, 34, 40, 0, LAYOUT(6, 10, { curve: 0, rake: 0, rowLabels: "numeric", rowLabelStart: "7" }), 0],
  [MAP.gala, "Terrace Bar", "ga", 20, 80, 60, 12, 0, {}, 80],
];

const ASPECT = "16/10";

function seatPlan() {
  const seat_map_sections = [];
  const seats = [];
  let seatN = 0;
  SECTIONS.forEach(([mapId, name, kind, x, y, width, height, rotation, layout, capacity], i) => {
    const section = { id: sid("seatSection", i + 1), seat_map_id: mapId, name, kind, x, y, width, height, rotation, layout, capacity: kind === "ga" ? capacity : layout.rows * layout.seatsPerRow, sort_order: i, created_at: daysAgo(90), updated_at: daysAgo(20) };
    seat_map_sections.push(section);
    generateSeats(section, ASPECT).forEach((seat, si) => {
      seatN += 1;
      const accessible = name === "Stalls Centre" && seat.rowLabel === "A" && si < 2;
      seats.push({
        id: sid("seat", seatN), seat_map_id: mapId, section_id: section.id, row_label: seat.rowLabel, seat_label: seat.seatLabel,
        x: seat.x, y: seat.y, kind: accessible ? (si === 0 ? "wheelchair" : "companion") : "standard", companion_of: null, active: true, created_at: daysAgo(90),
      });
    });
  });
  return { seat_map_sections, seats };
}

export function venuesSeed() {
  const venues = VENUES.map((v, i) => ({
    id: v.id, project_id: PROJECT_ID, name: v.name, type: v.type, status: v.key === "pier17" ? "Active" : v.key === "online" ? "Active" : "Active",
    description: v.description, address: v.address, city: v.city, region: v.region, postcode: v.postcode, country: v.country, timezone: v.timezone,
    latitude: v.latitude, longitude: v.longitude, parking_notes: v.parking, transit_notes: v.transit,
    seated_capacity: v.seated, standing_capacity: v.standing, spaces: v.spaces, amenities: v.amenities,
    contact_name: v.contactName, contact_email: v.contactEmail, contact_phone: v.contactPhone, website: v.website,
    cover_url: coverArt(`venue-${v.key}`, i), gallery: [], created_by: personId(11),
    metadata: { rating: [5, 5, 4, 5, 4, 5, 4, 5][i], tags: v.key === "lxFactory" ? ["Conference", "Industrial"] : [] },
    created_at: daysAgo(380 - i * 30), updated_at: daysAgo(5 + i * 3), deleted_at: null,
  }));

  const seat_maps = [
    { id: MAP.mainHall, venue_id: VENUE.lxFactory, name: "Main Hall — Theatre", status: "Active", config: { aspect: ASPECT, field: { shape: "stage", x: 30, y: 4, width: 40, height: 12, rotation: 0, label: "Main Stage" } }, metadata: { tiers: ["VIP", "Stalls", "Balcony"] } },
    { id: MAP.gala, venue_id: VENUE.pier17, name: "Rooftop — Gala Dinner", status: "Draft", config: { aspect: ASPECT, field: { shape: "stage", x: 38, y: 2, width: 24, height: 8, rotation: 0, label: "Stage" } }, metadata: {} },
  ].map((m) => ({ ...m, project_id: PROJECT_ID, created_by: personId(4), created_at: daysAgo(100), updated_at: daysAgo(9), deleted_at: null }));

  const { seat_map_sections, seats } = seatPlan();

  // The Summit's VIP buyers hold front-stalls chairs, front row first.
  const vipSeats = seats.filter((s) => s.section_id === seat_map_sections[0].id);
  const seat_assignments = [];
  let cursor = 0;
  ORDER_ROWS.filter((o) => o.event_id === EVENT.summit && o.metadata.tierId === "summit-vip" && !o.cancelled_at && o.status !== "refunded").forEach((order) => {
    for (let q = 0; q < order.quantity && cursor < vipSeats.length; q += 1) {
      const seat = vipSeats[cursor++];
      seat_assignments.push({
        id: sid("seatAssignment", seat_assignments.length + 1), event_id: EVENT.summit, seat_id: seat.id, order_id: order.id,
        attendee_name: order.buyer_name, attendee_email: order.buyer_email, ticket_id: "summit-vip", price: order.ticket_price,
        status: "sold", note: "", created_by: null, created_at: order.created_at, released_at: null,
      });
    }
  });

  const hall_maps = [{
    id: HALL.expo, project_id: PROJECT_ID, venue_id: VENUE.lxFactory, name: "LX Factory — Courtyard Expo", status: "Active",
    config: { aspect: "4/3", field: { shape: "none" } }, created_by: personId(4), metadata: { halls: ["Courtyard", "Print Room"] },
    created_at: daysAgo(80), updated_at: daysAgo(6), deleted_at: null,
  }];

  // [code, name, hall, size, price, x, y, w, h, exhibitor, status]
  const BOOTHS = [
    ["A1", "Kestrel Bikes", "Courtyard", "Premium", 4800, 6, 8, 18, 14, "Kestrel Bikes", "Occupied"],
    ["A2", "Orbit Audio", "Courtyard", "Premium", 4800, 28, 8, 18, 14, "Orbit Audio", "Occupied"],
    ["A3", "Atlas Coffee Bar", "Courtyard", "Large", 3200, 50, 8, 14, 14, "Atlas Coffee Roasters", "Occupied"],
    ["A4", "Fieldnote Press", "Courtyard", "Standard", 1800, 68, 8, 11, 11, "Fieldnote Press", "Reserved"],
    ["A5", "", "Courtyard", "Standard", 1800, 83, 8, 11, 11, "", "Available"],
    ["B1", "Lumio Labs", "Courtyard", "Large", 3200, 6, 32, 14, 12, "Lumio Labs", "Occupied"],
    ["B2", "Arcade Type Foundry", "Courtyard", "Standard", 1800, 24, 32, 11, 11, "Arcade Type Foundry", "Occupied"],
    ["B3", "", "Courtyard", "Standard", 1800, 39, 32, 11, 11, "", "Available"],
    ["B4", "Solace Hotels", "Courtyard", "Large", 3200, 54, 32, 14, 12, "Solace Hotels", "Reserved"],
    ["B5", "", "Courtyard", "Standard", 1800, 72, 32, 11, 11, "", "Available"],
    ["C1", "Paperplane UX", "Print Room", "Standard", 1500, 6, 60, 11, 11, "Paperplane UX", "Occupied"],
    ["C2", "Moss & Marble", "Print Room", "Standard", 1500, 21, 60, 11, 11, "Moss & Marble", "Occupied"],
    ["C3", "", "Print Room", "Standard", 1500, 36, 60, 11, 11, "", "Available"],
    ["C4", "Saltwater Films", "Print Room", "Standard", 1500, 51, 60, 11, 11, "Saltwater Films", "Reserved"],
    ["C5", "", "Print Room", "Standard", 1500, 66, 60, 11, 11, "", "Available"],
    ["D1", "Meridian Bank Lounge", "Print Room", "Premium", 5200, 6, 80, 26, 14, "Meridian Bank", "Occupied"],
    ["D2", "", "Print Room", "Large", 3200, 40, 80, 18, 14, "", "Available"],
    ["D3", "Copperleaf", "Print Room", "Standard", 1500, 66, 80, 11, 11, "Copperleaf", "Occupied"],
  ];
  const hall_booths = BOOTHS.map(([code, name, hall, size, price, x, y, width, height, exhibitor, status], i) => ({
    id: sid("booth", i + 1), hall_map_id: HALL.expo, code, name: name || `Booth ${code}`, kind: "booth", hall, size_class: size, price,
    x, y, width, height, rotation: 0, amenities: { power: true, wifi: true, tables: size === "Standard" ? 1 : 2 },
    metadata: { placed: true, status, exhibitor, notes: status === "Reserved" ? "Contract out for signature." : "" },
    active: true, sort_order: i, created_at: daysAgo(80), updated_at: daysAgo(4),
  }));

  const booth_assignments = BOOTHS.map((b, i) => [b, i]).filter(([b]) => b[10] !== "Available").map(([b, i], k) => ({
    id: sid("boothAssignment", k + 1), event_id: EVENT.summit, booth_id: sid("booth", i + 1), order_id: null,
    exhibitor_name: b[9], exhibitor_email: `partners@${b[9].toLowerCase().replace(/[^a-z]+/g, "")}.example`, ticket_id: null, price: b[4],
    status: b[10] === "Occupied" ? "sold" : "held", note: "", created_by: personId(4), created_at: daysAgo(40 - k), released_at: null,
  }));

  return { venues, seat_maps, seat_map_sections, seats, seat_assignments, hall_maps, hall_booths, booth_assignments };
}
